import { useRef } from 'react';
import { useTheme } from '../../hooks/useTheme';

export default function PlusMenu({ open, onClose, onFile, onScreenshot }) {
  const fileRef = useRef(null);
  const { cardHex, borderHex, textHex, hoverHex } = useTheme();

  const handleFile = (e) => {
    const files = Array.from(e.target.files ?? []);
    if (files.length) onFile(files);
    e.target.value = '';
    onClose();
  };

  if (!open) return null;

  return (
    <>
      <div style={{ position: 'fixed', inset: 0, zIndex: 98 }} onClick={onClose}/>
      <div style={{
        position: 'absolute', bottom: 44, left: 0, zIndex: 99,
        background: cardHex, border: `1px solid ${borderHex}`,
        borderRadius: 12, overflow: 'hidden', minWidth: 190,
        boxShadow: '0 8px 32px rgba(0,0,0,0.22)', animation: 'fadeUp 0.15s ease',
      }}>
        {[
          {
            label: 'Take screenshot',
            icon: (
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#6366f1" strokeWidth="2"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><polyline points="21 15 16 10 5 21"/></svg>
            ),
            action: () => { onScreenshot(); onClose(); },
          },
          {
            label: 'Add file',
            icon: (
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#6366f1" strokeWidth="2"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>
            ),
            action: () => fileRef.current?.click(),
          },
        ].map(({ label, icon, action }) => (
          <button key={label} onClick={action} style={{
            display: 'flex', alignItems: 'center', gap: 7,
            padding: '9px 14px', background: 'none', border: 'none',
            cursor: 'pointer', fontSize: 13.5, color: textHex,
            fontFamily: "'DM Sans', sans-serif", width: '100%', textAlign: 'left',
            transition: 'background 0.15s',
          }}
            onMouseEnter={(e) => { e.currentTarget.style.background = hoverHex; }}
            onMouseLeave={(e) => { e.currentTarget.style.background = 'none'; }}>
            {icon}{label}
          </button>
        ))}
        <input type="file" ref={fileRef} style={{ display: 'none' }} multiple onChange={handleFile}/>
      </div>
    </>
  );
}
